const form = $input.first().json;

const qp = form.formQueryParameters || {};
const instance  = (qp.instancia || qp.instance  || form.instance  || '').trim();
const remoteJid = (qp.whatsapp  || qp.remoteJid || form.remoteJid || '').trim();

const professor_nome = (qp.professor_nome || form.professor_nome || 'Professor(a)').trim();
const escola         = (qp.escola         || form.escola         || '').trim();
const diretoria      = (qp.diretoria      || form.diretoria      || '').trim();
const endereco       = (qp.endereco       || form.endereco       || '').trim();
const email_telefone = (qp.email_telefone || form.email_telefone || '').trim();

const diaLabel = { seg:'SEGUNDA-FEIRA', ter:'TERÇA-FEIRA', qua:'QUARTA-FEIRA', qui:'QUINTA-FEIRA', sex:'SEXTA-FEIRA' };
const diaSigla = { seg:'SEG', ter:'TER', qua:'QUA', qui:'QUI', sex:'SEX' };
const aulaHor  = { 1:'7h–7h50', 2:'7h50–8h40', 3:'8h55–9h45', 4:'9h45–10h35', 5:'10h35–11h15', 6:'12h15–13h15', 7:'13h15–13h45' };

const obs = {
  seg: (form['━━━ SEGUNDA-FEIRA ━━━'] || '').trim(),
  ter: (form['━━━ TERÇA-FEIRA ━━━']   || '').trim(),
  qua: (form['━━━ QUARTA-FEIRA ━━━']  || '').trim(),
  qui: (form['━━━ QUINTA-FEIRA ━━━']  || '').trim(),
  sex: (form['━━━ SEXTA-FEIRA ━━━']   || '').trim(),
};

// Leituras — BLOCO FIXO E INDEPENDENTE das aulas.
// Não tem relação pedagógica com nenhuma aula específica: é só uma
// leitura do dia. Fica só dentro de `meta`, nunca dentro de uma
// aula individual, e nunca é enviado pra IA reescrever.
// Se o professor preencheu -> vai exatamente como foi digitado.
// Se não preencheu -> fica string vazia (sem placeholder nenhum).
const meta = {
  instance, remoteJid, professor_nome, escola, diretoria, endereco, email_telefone,
  serie:  (form['Série / Turma'] || '').trim(),
  semana: (form['Semana (período)'] || '').trim(),
  obs_seg: obs.seg, obs_ter: obs.ter, obs_qua: obs.qua, obs_qui: obs.qui, obs_sex: obs.sex,
};

for (const slug of ['seg','ter','qua','qui','sex']) {
  const sigla = diaSigla[slug];
  meta[`${slug}_1_leitura`] = (form[`${sigla} — LEITURA DO DIA`]        || '').trim();
  meta[`${slug}_1_autor`]   = (form[`${sigla} — LEITURA | Autor`]        || '').trim();
  meta[`${slug}_1_genero`]  = (form[`${sigla} — LEITURA | Gênero textual`] || '').trim();
}

const aulasAtivas = [];

for (const slug of ['seg','ter','qua','qui','sex']) {
  const sigla = diaSigla[slug];

  for (const num of [1, 2, 3, 4, 5, 6, 7]) {
    const horario = aulaHor[num];
    const base    = `${sigla} ${num}ª Aula ${horario}`;

    const disciplina  = (form[`${base} | Disciplina`]        || '').trim();
    const tema        = (form[`${base} | Tema`]              || '').trim();
    const descricao   = (form[`${base} | Descrição da aula`] || '').trim();
    const continuacao = (form[`${base} | É continuação?`]    || 'Não — aula nova').trim();

    if (!disciplina && !tema) continue;

    // IMPORTANTE: a aula NÃO carrega leitura/autor/genero.
    // Esse bloco é independente e não passa pela IA.
    aulasAtivas.push({
      ...meta,
      slot: `${slug}_${num}`,
      dia: diaLabel[slug],
      numero: num,
      horario,
      disciplina, tema, descricao,
      continuacao,
    });
  }
}

return [{
  json: {
    ...meta,
    aulas_ativas: aulasAtivas,
    total_aulas:  aulasAtivas.length,
  }
}];

// Prepara o input para o nó de embeddings
// Lê do Mapear Form (nó que tem aulas_ativas)
const dados = $('🔧 Enriquecer Dados do Professor1').first().json;
const aulas = dados.aulas_ativas || [];

// Monta array de strings para embedding
const inputs = aulas.map(a =>
  [a.disciplina, a.tema, a.serie].filter(Boolean).join(' ')
);

return [{ json: { ...dados, embedding_inputs: inputs } }];

// Recebe embeddings e monta um item por aula para busca BNCC
const resp = $input.first().json;
const embeddings = resp.data?.map(d => d.embedding) || [];

// Recuperar dados originais do nó Mapear Form
const dados = $('🔧 Enriquecer Dados do Professor1').first().json;
const aulas = dados.aulas_ativas || [];

// ============================================================
// 🧹 NORMALIZAÇÃO DE SÉRIE E DISCIPLINA (mesma lógica do
// Orquestrador, node "🔍 Extrair Parâmetros") — garante que o
// filtro enviado ao Supabase bate com o texto salvo na tabela
// bncc_oficial, independente de como o professor digitou no
// formulário (com/sem acento, º vs °, colado, com turma, etc).
// ============================================================

function stripAccents(s) {
  return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function normalizarSerie(raw) {
  const norm = stripAccents(raw).toLowerCase();
  const ehMedio = /\bserie\b|\bmedio\b/.test(norm);

  // Pega o primeiro dígito 1-9 presente no texto (ex: "3ºANO A" -> "3")
  const digitoMatch = norm.match(/[1-9]/);
  if (!digitoMatch) return raw; // não achou dígito — mantém original como fallback

  const digito = digitoMatch[0];

  if (ehMedio) {
    const mapaMedio = { '1': '1ª série', '2': '2ª série', '3': '3ª série' };
    return mapaMedio[digito] || raw;
  }

  const mapaFundamental = {
    '1': '1º ano', '2': '2º ano', '3': '3º ano', '4': '4º ano', '5': '5º ano',
    '6': '6º ano', '7': '7º ano', '8': '8º ano', '9': '9º ano',
  };
  return mapaFundamental[digito] || raw;
}

// Mapa de disciplinas -> nome EXATO como está salvo em bncc_oficial.componente
const mapaDisciplina = {
  'matematica': 'Matemática',
  'matematicas': 'Matemática',
  'lingua portuguesa': 'Língua Portuguesa',
  'portugues': 'Língua Portuguesa',
  'alfabetizacao': 'Língua Portuguesa',
  'literatura': 'Língua Portuguesa',
  'redacao': 'Língua Portuguesa',
  'leitura': 'Língua Portuguesa',
  'ciencias': 'Ciências',
  'historia': 'História',
  'geografia': 'Geografia',
  'ingles': 'Inglês',
};

function normalizarDisciplina(raw) {
  const norm = stripAccents(raw).toLowerCase().trim();
  if (mapaDisciplina[norm]) return mapaDisciplina[norm];

  // tenta por inclusão (chave contida no texto, da mais longa pra mais curta)
  const chaves = Object.keys(mapaDisciplina).sort((a, b) => b.length - a.length);
  for (const k of chaves) {
    if (norm.includes(k)) return mapaDisciplina[k];
  }

  // não mapeada (ex: "MATIFIC", "TUTORIA") — mantém original.
  // É esperado que essas não achem habilidade BNCC mesmo.
  return raw;
}

return aulas.map((aula, i) => {
  const serieNormalizada = normalizarSerie(aula.serie);
  const disciplinaNormalizada = normalizarDisciplina(aula.disciplina);

  return {
    json: {
      query_embedding: embeddings[i] || [],
      filtro_serie: serieNormalizada,
      filtro_componente: disciplinaNormalizada,
      limite_escopos: 2,
      limite_bncc: 2,
      _slot: aula.slot,
      _disciplina: aula.disciplina,
      _disciplina_normalizada: disciplinaNormalizada,
      _tema: aula.tema,
      _serie: aula.serie,
      _serie_normalizada: serieNormalizada,
      _dia: aula.dia,
      _numero: aula.numero,
      _continuacao: aula.continuacao,
      _descricao: aula.descricao || '',
      _leitura: aula.leitura || '',
      _autor: aula.autor || '',
      _genero: aula.genero || '',
      _idx: i
    }
  };
});

// Agrupa resultados BNCC por aula e monta o prompt para OpenAI
const dados = $('🔧 Enriquecer Dados do Professor1').first().json;
const aulas = dados.aulas_ativas || [];
const allItems = $input.all();

const safe = (v, fb='') => v == null ? fb : String(v).trim() || fb;
const TEXTO_NAO_ENCONTRADA = 'Habilidade não encontrada na base de dados';

function tryParseArray(v) {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string') {
    try {
      const p = JSON.parse(v);
      if (Array.isArray(p)) return p;
    } catch (e) { /* not JSON, ignore */ }
  }
  return null;
}

const porAula = {}; // index (0..N-1) -> array de resultados bncc
let metodo = 'nenhum';

// --- Camada 1: resposta em TEXTO BRUTO, 1 item de entrada = 1 item de
// saída, na MESMA ordem que `aulas`. Este é o caminho principal desde
// que o node Supabase foi configurado com responseFormat: "text".
if (allItems.length === aulas.length) {
  let ok = true;
  const tentativa = {};
  allItems.forEach((item, i) => {
    // Com responseFormat "text" o corpo cru fica em item.json.data
    const bruto = item.json && item.json.data !== undefined ? item.json.data : item.json;
    const arr = tryParseArray(bruto);
    if (arr === null) { ok = false; return; }
    tentativa[i] = arr;
  });
  if (ok) {
    Object.assign(porAula, tentativa);
    metodo = 'texto_bruto_indexado';
  }
}

// --- Camada 2: fallback via pairedItem nativo do n8n, caso a resposta
// ainda tenha vindo splitada em múltiplos itens por algum motivo.
if (metodo === 'nenhum') {
  let usouPairedItem = true;
  const tentativa = {};
  for (const item of allItems) {
    const idx = item.pairedItem && typeof item.pairedItem.item === 'number'
      ? item.pairedItem.item
      : null;
    if (idx === null) { usouPairedItem = false; break; }
    const linha = tryParseArray(item.json) ? null : item.json; // item já é 1 linha (objeto)
    if (!tentativa[idx]) tentativa[idx] = [];
    tentativa[idx].push(linha || item.json);
  }
  if (usouPairedItem) {
    Object.assign(porAula, tentativa);
    metodo = 'paired_item';
  }
}

// --- Camada 3: último recurso — blocos sequenciais de tamanho fixo.
if (metodo === 'nenhum') {
  const porBloco = aulas.length ? Math.round(allItems.length / aulas.length) || 2 : 2;
  allItems.forEach((item, pos) => {
    const idx = Math.floor(pos / porBloco);
    if (!porAula[idx]) porAula[idx] = [];
    const bruto = item.json && item.json.data !== undefined ? item.json.data : item.json;
    const arr = tryParseArray(bruto);
    if (arr) { porAula[idx] = porAula[idx].concat(arr); }
    else { porAula[idx].push(item.json); }
  });
  metodo = 'blocos_fixos';
}

// Mapa determinístico slot -> habilidades (código + descritor completo).
// Esta é a ÚNICA fonte usada no documento final para o campo
// "habilidades" — não depende da IA reescrever/copiar corretamente.
const habilidadesPorSlot = {};

const aulasPrompt = aulas.map((aula, i) => {
  const bncc = porAula[i] || [];

  const habs = [], ctxs = [];
  bncc.forEach(r => {
    if (r && r.fonte === 'bncc_oficial') {
      const h = safe(r.codigo) + ': ' + safe(r.conteudo);
      if (!habs.includes(h)) habs.push(h);
    } else if (r && r.titulo) {
      ctxs.push('[Exemplo] ' + safe(r.titulo) + ': ' + safe(r.conteudo));
    }
  });

  habilidadesPorSlot[aula.slot] = habs.length ? habs.join(' | ') : TEXTO_NAO_ENCONTRADA;

  return 'AULA ' + (i+1) + ' [' + aula.slot + ']:\n' +
    '- Disciplina: ' + aula.disciplina + '\n' +
    '- Tema: ' + aula.tema + '\n' +
    '- Série: ' + aula.serie + '\n' +
    '- Dia: ' + aula.dia + ' — ' + aula.numero + 'ª aula\n' +
    '- Continuação: ' + aula.continuacao + '\n' +
    (aula.descricao ? '- Contexto extra: ' + aula.descricao + '\n' : '') +
    '- Habilidades BNCC: ' + (habs.join(' | ') || 'Não localizada') + '\n' +
    '- Contexto: ' + (ctxs.join(' | ') || 'N/A');
}).join('\n\n---\n\n');

const systemPrompt = `Você é especialista em planejamento pedagógico SEE-SP.

REGRAS ABSOLUTAS:
1. Use a(s) habilidade(s) BNCC de cada aula (campo "Habilidades BNCC" acima) como
   referência pedagógica para escrever "conteudo", "objetivos" e "desenvolvimento" —
   respeitando a Disciplina e o Tema informados para AQUELA aula. Se a habilidade
   listada parecer de outra disciplina/tema, priorize a Disciplina e o Tema da
   aula ao escrever o conteúdo (nunca invente uma disciplina diferente da
   informada). NÃO copie a habilidade dentro desses campos, e NÃO invente códigos.
2. Se continuação: conteúdo inicia com "Dando continuidade,"
3. Responda APENAS com JSON válido — sem texto fora do JSON
4. NÃO inclua leitura, autor ou gênero textual na resposta — isso é um bloco
   separado e não faz parte do conteúdo das aulas.
5. NÃO inclua o campo "habilidades" na sua resposta — ele é preenchido
   automaticamente pelo sistema a partir da base de dados BNCC, fora do seu
   escopo.

Para CADA aula gere:
- slot: exatamente como fornecido (ex: seg_1, qui_3)
- disciplina, conteudo (2-3 tópicos verbos infinitivo),
  objetivos (2 Bloom), desenvolvimento (1ª pessoa futuro, 8-12 linhas)

FORMATO: {"aulas":[{"slot":"seg_1","disciplina":"...","conteudo":"...","objetivos":"...","desenvolvimento":"..."}]}`;

return [{
  json: {
    _dados_originais: dados,
    _total_aulas: aulas.length,
    _habilidades_por_slot: habilidadesPorSlot,
    _debug_metodo_agrupamento: metodo,
    system: systemPrompt,
    user: 'Gere conteúdo para ' + aulas.length + ' aulas:\n\n' + aulasPrompt + '\n\nResponda APENAS com o JSON.'
  }
}];

const resp = $input.first().json;
const prompt_no = $('🔧 Montar Prompt Batch1').first().json;
const dados = prompt_no._dados_originais;
const totalAulas = prompt_no._total_aulas;
const aulas = dados.aulas_ativas || [];
const habilidadesPorSlot = prompt_no._habilidades_por_slot || {};

const safe = (v, fb='') => v == null ? fb : String(v).trim() || fb;

const TEXTO_NAO_ENCONTRADA = 'Habilidade não encontrada na base de dados';

// Parsear resposta OpenAI
const content = resp.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(content); }
catch(e) {
  const m = content.match(/\{[\s\S]*\}/);
  parsed = m ? JSON.parse(m[0]) : { aulas: [] };
}

const aulasGeradas = parsed.aulas || [];
console.log('[BATCH v4] ✅ ' + aulasGeradas.length + '/' + totalAulas + ' aulas geradas');

// Montar payload de slots (SEM leitura/autor/genero — isso é bloco
// fixo, tratado separadamente a partir de `dados`, nunca da IA).
// O campo "_habilidades" vem SEMPRE do mapa determinístico
// habilidadesPorSlot, nunca do texto gerado pela IA — garante
// código + descritor completo (ou o texto padrão de não encontrada).
const dias = ['seg','ter','qua','qui','sex'];
const payload = {};
for (const d of dias) {
  for (let n = 1; n <= 7; n++) {
    const s = d + '_' + n;
    payload[s + '_disciplina'] = '';
    payload[s + '_conteudo'] = '';
    payload[s + '_habilidades'] = habilidadesPorSlot[s] || '';
    payload[s + '_objetivos'] = '';
    payload[s + '_desenvolvimento'] = '';
  }
}

for (const ag of aulasGeradas) {
  const s = ag.slot;
  if (s) {
    payload[s + '_disciplina']      = safe(ag.disciplina);
    payload[s + '_conteudo']        = safe(ag.conteudo);
    payload[s + '_habilidades']     = habilidadesPorSlot[s] || TEXTO_NAO_ENCONTRADA;
    payload[s + '_objetivos']       = safe(ag.objetivos);
    payload[s + '_desenvolvimento'] = safe(ag.desenvolvimento);
  }
}

// Fallback para slots não retornados pela IA
const slotsGerados  = aulasGeradas.map(a => a.slot).filter(Boolean);
const slotsFaltando = aulas.map(a => a.slot).filter(s => !slotsGerados.includes(s));
for (const slot of slotsFaltando) {
  const aula = aulas.find(a => a.slot === slot);
  if (aula) {
    payload[slot + '_disciplina']  = aula.disciplina;
    payload[slot + '_conteudo']    = aula.tema;
    payload[slot + '_habilidades'] = habilidadesPorSlot[slot] || TEXTO_NAO_ENCONTRADA;
  }
}

console.log('[BATCH v4] Slots gerados: ' + slotsGerados.join(', '));
console.log('[BATCH v4] Slots faltando: ' + (slotsFaltando.join(', ') || 'Nenhum'));

return [{
  json: {
    professor:      dados.professor_nome || '',
    serie:          dados.serie || '',
    escola:         dados.escola || '',
    diretoria:      dados.diretoria || '',
    endereco:       dados.endereco || '',
    email_telefone: dados.email_telefone || '',
    semana:         dados.semana || '',
    obs_seg: dados.obs_seg || '', obs_ter: dados.obs_ter || '',
    obs_qua: dados.obs_qua || '', obs_qui: dados.obs_qui || '',
    obs_sex: dados.obs_sex || '',
    instance:       dados.instance || '',
    remoteJid:      dados.remoteJid || '',
    // Bloco de LEITURA — fixo e independente, exatamente como veio
    // do formulário (vazio se o professor não preencheu, sem
    // nenhum placeholder).
    seg_1_leitura: dados.seg_1_leitura || '', seg_1_autor: dados.seg_1_autor || '', seg_1_genero: dados.seg_1_genero || '',
    ter_1_leitura: dados.ter_1_leitura || '', ter_1_autor: dados.ter_1_autor || '', ter_1_genero: dados.ter_1_genero || '',
    qua_1_leitura: dados.qua_1_leitura || '', qua_1_autor: dados.qua_1_autor || '', qua_1_genero: dados.qua_1_genero || '',
    qui_1_leitura: dados.qui_1_leitura || '', qui_1_autor: dados.qui_1_autor || '', qui_1_genero: dados.qui_1_genero || '',
    sex_1_leitura: dados.sex_1_leitura || '', sex_1_autor: dados.sex_1_autor || '', sex_1_genero: dados.sex_1_genero || '',
    total_processado: aulasGeradas.length,
    total_esperado:   totalAulas,
    ...payload,
  }
}];

// Junta os dados do formulário com os dados cadastrais do
// professor vindos do Supabase (tabela "professores"),
// buscados por telefone = remoteJid.
//
// Colunas reais da tabela (confirmadas no node
// "💾 Criar Usuário no Banco" do Orquestrador):
//   nome, email, telefone, "Nome da escola", "Diretoria de ensino"
//
// Não existe coluna de endereço nem campo combinado
// email_telefone — construímos esse aqui a partir de email + telefone.

const dadosForm = $('📦 Mapear Form → Aulas Ativas1').first().json;
const registros = $input.all().map(i => i.json);
const professor = registros[0] || {};

const professorEncontrado = !!(professor.id || professor.telefone);

const nome      = professor['nome']            || dadosForm.professor_nome || 'Professor(a)';
const escola    = professor['Nome da escola']   || dadosForm.escola         || '';
const diretoria = professor['Diretoria de ensino'] || dadosForm.diretoria   || '';
const email     = professor['email']            || '';
const telefone  = professor['telefone']         || dadosForm.remoteJid     || '';

const emailTelefone = [email, telefone].filter(Boolean).join(' | ') || dadosForm.email_telefone || '';

if (!professorEncontrado) {
  console.log('[Buscar Professor] Nenhum professor encontrado para telefone: ' + dadosForm.remoteJid);
}

return [{
  json: {
    ...dadosForm,
    professor_nome: nome,
    escola,
    diretoria,
    email_telefone: emailTelefone,
    // endereco: mantém o que já veio do form/querystring (não há
    // coluna de endereço na tabela professores ainda)
  }
}];
